@php
 $u=auth()->user();
 $role=$u->is_admin?'admin':'seller';
 $vouchers=\Illuminate\Support\Facades\DB::table('commerce_vouchers')->when($u->is_admin,fn($q)=>$q->whereNull('seller_id'),fn($q)=>$q->where('seller_id',$u->id))->get();
 $products=$u->is_admin?collect():\App\Models\Product::where('seller_id',$u->id)->where('status','active')->orderBy('name')->get();
@endphp
<div class="card" id="platform-vouchers"><div class="card-head"><h2>{{ $u->is_admin?'Platform and shipping':'Store' }} vouchers</h2></div><div class="card-pad"><form style="display:grid;gap:12px" method="POST" action="{{ route($role.'.commerce.voucher') }}">@csrf<div class="form-grid-2"><label class="form-row">Code (4–12 letters/digits)<input name="code" pattern="[A-Za-z0-9]{4,12}" minlength="4" maxlength="12" required></label><label class="form-row">Type<select class="select" name="kind">@if($u->is_admin)<option value="platform">Platform discount</option><option value="shipping">Shipping discount</option>@else<option value="store">Store discount</option>@endif</select></label><label class="form-row">Display<select class="select" name="display_mode"><option value="claimable">Claimable on shop</option><option value="code_only">Code only</option></select></label><label class="form-row">Discount<select class="select" name="discount_type"><option value="fixed">Fixed PHP amount</option><option value="percent">Percentage</option></select></label><label class="form-row">Amount / percent<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="form-row">Maximum discount (optional PHP)<input name="cap" type="number" min="0.01" step="0.01"></label><label class="form-row">Minimum spend (PHP)<input name="minimum_spend" type="number" min="0" step="0.01" value="0" required></label><label class="form-row">Starts<input name="starts_at" type="datetime-local" required></label><label class="form-row">Ends<input name="ends_at" type="datetime-local" required></label><label class="form-row">Total uses<input name="usage_limit" type="number" min="1" required></label><label class="form-row">Uses per buyer<input name="per_buyer_limit" type="number" min="1" value="1" required></label></div>@if(!$u->is_admin)<label class="form-row">Applicable products (leave clear for all products)<select class="select" name="product_ids[]" multiple>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->name }}</option>@endforeach</select></label>@endif<button class="btn btn-primary">Create voucher</button></form>@foreach($vouchers as $voucher)<div style="padding:12px 0;border-top:1px solid var(--border)">{{ $voucher->code }} · {{ $voucher->display_mode }} · {{ $voucher->starts_at }}–{{ $voucher->ends_at }} @if($voucher->is_active)<form style="display:inline" method="POST" action="{{ route($role.'.commerce.end',['voucher',$voucher->id]) }}">@csrf<button class="btn btn-sm btn-outline">End voucher</button></form>@else Ended @endif</div>@endforeach</div></div>
